/* Spicy Gecko 96 by LightAndy1 — https://uiverse.io/LightAndy1/spicy-gecko-96 */
.input {
  margin-top: 1rem;
  border-radius: 10px;
  outline: 2px solid #00a6fb;
  border: 0;
  font-family: "Montserrat", sans-serif;
  background-color: #d6f1ff;
  outline-offset: 3px;
  padding: 10px 12.5px;
  transition: all 0.2s ease;
  width: 250px;
}

.input:hover {
  background-color: #fff;
}

.input:focus {
  outline-offset: -6px;
  background-color: #d6f1ff;
}
